CREATE OR REPLACE FUNCTION public.set_equipment_target(_target uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; affected integer; BEGIN IF auth.uid() IS NULL OR nullif(auth.jwt()->>'session_id','') IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; sid:=(auth.jwt()->>'session_id')::uuid; IF _target IS NULL OR _target=auth.uid() THEN DELETE FROM equipment_view_sessions WHERE session_id=sid AND user_id=auth.uid(); RETURN auth.uid(); END IF; IF NOT public.equipment_target_allowed(_target,false) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO equipment_view_sessions(session_id,user_id,target_user_id) VALUES(sid,auth.uid(),_target) ON CONFLICT(session_id) DO UPDATE SET target_user_id=excluded.target_user_id,updated_at=now() WHERE equipment_view_sessions.user_id=auth.uid(); GET DIAGNOSTICS affected=ROW_COUNT; IF affected<>1 THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN _target; END $$;
CREATE POLICY equipment_monitor_live_only ON public.equipment AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT public.equipment_view_active() OR deleted_at IS NULL);
CREATE POLICY history_monitor_live_only ON public.equipment_history AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT public.equipment_view_active() OR deleted_at IS NULL);
CREATE POLICY attachments_monitor_authorized_insert ON public.equipment_history_attachments AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT public.equipment_view_active() OR (user_id=auth.uid() AND EXISTS(SELECT 1 FROM equipment_history h JOIN equipment e ON e.id=h.equipment_id WHERE h.id=history_id AND e.user_id=public.equipment_view_target() AND public.equipment_target_allowed(e.user_id,true))));
CREATE POLICY equipment_names_monitor_no_delete ON public.equipment_names AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT public.equipment_view_active());
CREATE OR REPLACE FUNCTION public.set_my_pin(_pin text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR public.equipment_view_active() OR _pin !~ '^\d{4}$' OR public.is_admin_account(auth.uid()) THEN RAISE EXCEPTION 'invalid'; END IF; INSERT INTO public.account_pins(user_id,pin) VALUES(auth.uid(),_pin) ON CONFLICT(user_id) DO UPDATE SET pin=EXCLUDED.pin,updated_at=now(); END $$;